package com.orderflow.notification.outbox;import tools.jackson.core.JacksonException;import tools.jackson.databind.ObjectMapper;import com.orderflow.events.EventMetadata;import com.orderflow.notification.config.OutboxProperties;import java.sql.*;import java.time.*;import java.util.*;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import org.springframework.transaction.annotation.Transactional;@Repository public class OutboxStore{private final JdbcTemplate jdbc;private final ObjectMapper mapper;private final OutboxProperties p;private final Clock clock;public OutboxStore(JdbcTemplate j,ObjectMapper m,OutboxProperties p,Clock c){jdbc=j;mapper=m;this.p=p;clock=c;}public void enqueue(String topic,UUID key,Object event,EventMetadata m){try{Instant n=Instant.now(clock);jdbc.update("INSERT INTO outbox_event(id,aggregate_type,aggregate_id,event_type,event_version,topic,message_key,payload,correlation_id,causation_id,status,attempts,available_at,created_at)VALUES(?,?,?,?,?,?,?,CAST(? AS jsonb),?,?,'NEW',0,?,?)",m.eventId(),m.aggregateType(),m.aggregateId(),m.eventType().name(),m.eventVersion(),topic,key.toString(),mapper.writeValueAsString(event),m.correlationId(),m.causationId(),Timestamp.from(n),Timestamp.from(n));}catch(JacksonException e){throw new IllegalStateException("Unable to serialize notification event",e);}}@Transactional public List<OutboxMessage>claim(String owner){Instant n=Instant.now(clock);var rows=jdbc.query("SELECT id,topic,message_key,event_type,event_version,payload::text,attempts FROM outbox_event current_event WHERE ((status = 'NEW' AND available_at <= ?) OR (status = 'IN_PROGRESS' AND locked_at < ?)) AND NOT EXISTS ( SELECT 1 FROM outbox_event earlier WHERE earlier.topic = current_event.topic AND earlier.message_key = current_event.message_key AND earlier.event_sequence < current_event.event_sequence AND earlier.status <> 'PUBLISHED') ORDER BY event_sequence FOR UPDATE SKIP LOCKED LIMIT ?",(r,i)->new OutboxMessage(r.getObject(1,UUID.class),r.getString(2),r.getString(3),r.getString(4),r.getInt(5),r.getString(6),r.getInt(7)),Timestamp.from(n),Timestamp.from(n.minus(p.lockTimeout())),p.batchSize());rows.forEach(r->jdbc.update("UPDATE outbox_event SET status='IN_PROGRESS',locked_at=?,locked_by=? WHERE id=?",Timestamp.from(n),owner,r.id()));return rows;}public void published(UUID id,String o){jdbc.update("UPDATE outbox_event SET status='PUBLISHED',published_at=?,locked_at=NULL,locked_by=NULL,last_error_code=NULL WHERE id=? AND locked_by=?",Timestamp.from(Instant.now(clock)),id,o);}public void failed(OutboxMessage m,String o,String code){int a=m.attempts()+1;jdbc.update("UPDATE outbox_event SET status=?,attempts=?,available_at=?,last_error_code=?,locked_at=NULL,locked_by=NULL WHERE id=? AND locked_by=?",a>=p.maxAttempts()?"FAILED":"NEW",a,Timestamp.from(Instant.now(clock).plus(p.retryBaseDelay().multipliedBy(1L<<Math.min(a-1,10)))),code.substring(0,Math.min(200,code.length())),m.id(),o);}public long backlog(){Long n=jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE status IN('NEW','IN_PROGRESS')",Long.class);return n==null?0:n;}public long failedCount(){Long n=jdbc.queryForObject("SELECT count(*) FROM outbox_event WHERE status='FAILED'",Long.class);return n==null?0:n;}}
